import{_ as t,o as s,a,a2 as n}from"./chunks/framework.DCcmcJcL.js";const u=JSON.parse('{"title":"Configure Elasticsearch","description":"","frontmatter":{},"headers":[],"relativePath":"performance/configure-elasticsearch.md","filePath":"performance/configure-elasticsearch.md","lastUpdated":1790143103000}'),i={name:"performance/configure-elasticsearch.md"};function o(d,e,r,c,h,l){return s(),a("div",null,e[0]||(e[0]=[n(`<h1 id="configure-elasticsearch" tabindex="-1">Configure Elasticsearch <a class="header-anchor" href="#configure-elasticsearch" aria-label="Permalink to &quot;Configure Elasticsearch&quot;">​</a></h1><p>This guide connects a Bagisto store to an Elasticsearch cluster, builds the product index and checks it before going live. How the engine is chosen for each context, what goes into a document and how the index stays current are explained on <a href="./../advanced/search-engines.html">Search Engines</a>.</p><h2 id="when-you-need-it" tabindex="-1">When You Need It <a class="header-anchor" href="#when-you-need-it" aria-label="Permalink to &quot;When You Need It&quot;">​</a></h2><p>Use Elasticsearch when searching and filtering the catalog in the database is too slow for your catalog. You need:</p><ul><li><strong>Elasticsearch 8.</strong> Bagisto requires the <code>elasticsearch/elasticsearch</code> client <code>^8.10</code>, and the client refuses a server that fails its product check.</li><li><strong>The PHP <code>curl</code> extension</strong>, which Bagisto&#39;s <code>composer.json</code> already requires.</li><li><strong>A queue worker</strong>, so product saves update the index outside the request. See <a href="./../advanced/queue-jobs-scheduling.html#running-workers-in-production">Queues, Jobs and Scheduling</a>.</li></ul><h2 id="step-1-check-the-cluster-answers" tabindex="-1">Step 1: Check the Cluster Answers <a class="header-anchor" href="#step-1-check-the-cluster-answers" aria-label="Permalink to &quot;Step 1: Check the Cluster Answers&quot;">​</a></h2><p>Run this from the application server. A default Elasticsearch 8 install enables security and TLS:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --cacert</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/http_ca.crt</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> elastic</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://localhost:9200</span></span></code></pre></div><p>A reachable cluster returns JSON with its <code>cluster_name</code> and <code>version.number</code>.</p><h2 id="step-2-enter-the-connection-settings" tabindex="-1">Step 2: Enter the Connection Settings <a class="header-anchor" href="#step-2-enter-the-connection-settings" aria-label="Permalink to &quot;Step 2: Enter the Connection Settings&quot;">​</a></h2><p>Bagisto builds its client from <code>config/elasticsearch.php</code>, which reads <code>.env</code>. Settings saved in the admin are copied over it when the application boots, and any admin setting left empty keeps the <code>.env</code> value; see <a href="./../advanced/search-engines.html#applying-the-settings-at-boot">Search Engines</a>. On Bagisto 2.4 the connection comes from <code>.env</code> and <code>config/elasticsearch.php</code> only, and the engine is chosen with the search settings of the catalog configuration.</p><p>Enter the settings in the admin, in <code>.env</code>, or both; an empty admin field keeps the <code>.env</code> value.</p><h3 id="settings-in-the-admin" tabindex="-1">Settings in the Admin <a class="header-anchor" href="#settings-in-the-admin" aria-label="Permalink to &quot;Settings in the Admin&quot;">​</a></h3><p>The settings are in the <strong>Search Engines</strong> configuration section.</p><ol><li><p>Under <strong>General</strong>, switch on <strong>Enable External Search Engine</strong> (<code>search_engines.general.settings.enabled</code>) and set <strong>Default Search Engine</strong> to <strong>Elasticsearch</strong>.</p></li><li><p>Leave <strong>Admin Search Mode</strong> and <strong>Storefront Search Mode</strong> on <strong>Use Default</strong>, or set one of them to <strong>Database</strong> to keep that side of the store on the database.</p></li><li><p>Under <strong>Elasticsearch</strong>, choose the <strong>Authentication</strong> type and fill in the fields it shows:</p><table tabindex="0"><thead><tr><th>Authentication type</th><th>Fields</th></tr></thead><tbody><tr><td><code>none</code></td><td>Hosts</td></tr><tr><td><code>basic</code></td><td>Hosts, username, password</td></tr><tr><td><code>api_key</code></td><td>Hosts, API key</td></tr><tr><td><code>cloud_api_key</code></td><td>Cloud ID, API key</td></tr><tr><td><code>cloud_basic</code></td><td>Cloud ID, username, password</td></tr></tbody></table><p><strong>Hosts</strong> takes one or more comma-separated URLs. Set a lowercase <strong>Index Prefix</strong> when more than one store or environment shares the cluster: the prefix is used as typed, and Elasticsearch rejects index names with uppercase letters.</p></li><li><p>Click <strong>Test Connection</strong>. It tries the values on the form before they&#39;re saved.</p></li><li><p>Save the configuration.</p></li></ol><h3 id="settings-in-env" tabindex="-1">Settings in <code>.env</code> <a class="header-anchor" href="#settings-in-env" aria-label="Permalink to &quot;Settings in \`.env\`&quot;">​</a></h3><p>None of these keys is in <code>.env.example</code>; add the ones you need:</p><div class="language-properties vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">properties</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ELASTICSEARCH_HOST</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=https://localhost:9200</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ELASTICSEARCH_USER</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ELASTICSEARCH_PASS</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ELASTICSEARCH_API_KEY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ELASTICSEARCH_CLOUD_ID</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ELASTICSEARCH_INDEX_PREFIX</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span></span></code></pre></div><details class="details custom-block"><summary>How the <code>.env</code> Keys Map to <code>config/elasticsearch.php</code></summary><table tabindex="0"><thead><tr><th><code>.env</code> key</th><th><code>config/elasticsearch.php</code></th></tr></thead><tbody><tr><td><code>ELASTICSEARCH_HOST</code></td><td><code>connections.default.hosts</code> and <code>connections.api.hosts</code> (one host)</td></tr><tr><td><code>ELASTICSEARCH_USER</code>, <code>ELASTICSEARCH_PASS</code></td><td><code>connections.default.user</code>, <code>.pass</code> and <code>connections.cloud.user</code>, <code>.pass</code></td></tr><tr><td><code>ELASTICSEARCH_API_KEY</code></td><td><code>connections.api.key</code> and <code>connections.cloud.api_key</code></td></tr><tr><td><code>ELASTICSEARCH_CLOUD_ID</code></td><td><code>connections.cloud.id</code></td></tr><tr><td><code>ELASTICSEARCH_INDEX_PREFIX</code></td><td><code>index_prefix</code></td></tr></tbody></table><p><code>config/elasticsearch.php</code> sets <code>&#39;connection&#39; =&gt; &#39;default&#39;</code> with no environment variable, so an API key or a Cloud ID in <code>.env</code> is only used once the connection is switched to <code>api</code> or <code>cloud</code>. To switch it, choose the matching authentication type in the admin and leave its credential fields empty; the credentials still come from <code>.env</code>.</p></details><p><code>caBundle</code> (the CA certificate path for a cluster with its own certificate authority) and <code>retries</code> have no environment variable, so set them in <code>config/elasticsearch.php</code>, which belongs to your application. On a server that caches its configuration, run <code>php artisan config:cache</code> again after editing <code>.env</code>.</p><p><a id="build-the-index"></a></p><h2 id="step-3-build-the-index" tabindex="-1">Step 3: Build the Index <a class="header-anchor" href="#step-3-build-the-index" aria-label="Permalink to &quot;Step 3: Build the Index&quot;">​</a></h2><p>With the engine enabled, build every index:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> indexer:index</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --type=search</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --mode=full</span></span></code></pre></div><p>The command skips <code>search</code> unless an external engine is enabled, and does nothing for it without <code>--mode=full</code>. On Bagisto 2.4 the type is <code>elastic</code>. Run it again whenever what a document holds changes: after changing the index prefix (the store then reads new index names), switching an attribute to filterable, adding a customer group, renaming categories, and upgrading to Bagisto 2.5, whose documents added <code>category_name</code>.</p><p>After the first build, product saves and imports dispatch <code>IndexProducts</code> and <code>DeleteProducts</code> to the queue, so keep a worker running; see <a href="./../advanced/queue-jobs-scheduling.html#running-workers-in-production">Queues, Jobs and Scheduling</a>.</p><h2 id="test-it" tabindex="-1">Test It <a class="header-anchor" href="#test-it" aria-label="Permalink to &quot;Test It&quot;">​</a></h2><ol><li><p>List the product indices. There is one per channel and locale, named <code>{prefix}products_{channel}_{locale}_index</code>, with the channel and locale codes lowercased:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --cacert</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/http_ca.crt</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> elastic</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;https://localhost:9200/_cat/indices/*products_*?v&#39;</span></span></code></pre></div><p><code>docs.count</code> for an index matches the number of products assigned to that channel.</p></li><li><p>Query one index directly:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --cacert</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/http_ca.crt</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> elastic</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;https://localhost:9200/products_default_en_index/_search?q=name:shirt&amp;size=1&#39;</span></span></code></pre></div></li><li><p>Open the admin&#39;s About page. When the tested values match the saved settings, its search section shows the connection test&#39;s verdict and the cluster version for five minutes.</p></li></ol><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><p><strong>Test Connection</strong> reports one of these statuses:</p><table tabindex="0"><thead><tr><th>Message (status)</th><th>Cause</th></tr></thead><tbody><tr><td>Elasticsearch is available (<code>available</code>)</td><td>The cluster answered; the response includes the host, cluster name and version</td></tr><tr><td>Elasticsearch did not answer (<code>unreachable</code>)</td><td>No node answered, the server returned an error, or the request failed for another reason. Check the host, the port and the network path from the application server</td></tr><tr><td>Elasticsearch rejected the credentials (<code>unauthorized</code>)</td><td>The server answered <code>401</code> or <code>403</code>. The credentials don&#39;t match the authentication type</td></tr><tr><td>The host answered but is not a supported Elasticsearch server (<code>incompatible</code>)</td><td>The client&#39;s product check failed: the host isn&#39;t Elasticsearch 8, or something else answers on that address</td></tr><tr><td>The Elasticsearch connection is not configured (<code>misconfigured</code>)</td><td>The client couldn&#39;t be built from the settings (an <code>InvalidArgumentException</code>), for example a missing connection or an unusable value</td></tr></tbody></table><p>Other problems:</p><table tabindex="0"><thead><tr><th>Problem</th><th>Fix</th></tr></thead><tbody><tr><td>The storefront still searches the database</td><td><strong>Enable External Search Engine</strong> is off, or <strong>Storefront Search Mode</strong> is set to <strong>Database</strong></td></tr><tr><td>Products are missing from results</td><td>Run the full reindex; check the queue worker is running and the product is assigned to the channel</td></tr><tr><td>A filter on a new filterable attribute returns nothing</td><td>Documents only carry the attributes that were filterable when they were written; run the full reindex</td></tr><tr><td><code>indexer:index --type=search</code> finishes instantly</td><td>The external engine is disabled, or <code>--mode=full</code> is missing</td></tr><tr><td>Indexing fails with an invalid index name</td><td>The index prefix contains uppercase letters; change it to lowercase and reindex</td></tr><tr><td>An upgraded store lost its connection</td><td>See the first item under <a href="#things-to-watch">Things to Watch</a></td></tr></tbody></table><h2 id="things-to-watch" tabindex="-1">Things to Watch <a class="header-anchor" href="#things-to-watch" aria-label="Permalink to &quot;Things to Watch&quot;">​</a></h2><ul><li><strong>Upgrading a store that keeps its credentials in <code>.env</code>.</strong> After the Bagisto 2.5 migrations, a cluster behind credentials, an API key or a Cloud ID can become unreachable. Set the authentication type in the admin, re-enter the host and credentials, and test the connection; see <a href="https://github.com/bagisto/bagisto/blob/master/UPGRADE.md#elasticsearch-connection-settings-are-now-recorded-in-the-admin" target="_blank" rel="noreferrer"><code>UPGRADE.md</code></a>.</li><li><strong>Secure the cluster.</strong> Use <code>api_key</code> or <code>basic</code> authentication over HTTPS, and set <code>caBundle</code> when the cluster&#39;s certificate isn&#39;t signed by a public authority.</li><li><strong>Give each environment its own index prefix.</strong> Without one, staging and production on a shared cluster read and write the same <code>products_*</code> indices.</li><li><strong>Don&#39;t index on the <code>sync</code> queue.</strong> With <code>QUEUE_CONNECTION=sync</code> every product save waits for Elasticsearch.</li><li><strong>Scheduled price changes don&#39;t reach the index.</strong> A store that sorts or filters by price on Elasticsearch needs a full search reindex after the daily price and catalog rule reindexes; see <a href="./../advanced/search-engines.html#things-to-watch">Search Engines</a>.</li><li><strong>Restart long-running processes after changing the settings.</strong> They&#39;re applied when the application boots, so run <code>php artisan queue:restart</code>, and <code>php artisan octane:reload</code> on <a href="./configure-laravel-octane.html">Octane</a>.</li></ul><h2 id="related-pages" tabindex="-1">Related Pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related Pages&quot;">​</a></h2><ul><li><a href="./../advanced/search-engines.html">Search Engines</a>: how queries are routed, the document, the contracts and indexing.</li><li><a href="./../advanced/queue-jobs-scheduling.html">Queues, Jobs and Scheduling</a>: running the indexing jobs on a worker.</li><li><a href="./configure-fpc.html">Configure Full Page Cache</a>: caching the storefront pages that search results appear on.</li></ul>`,37)]))}const g=t(i,[["render",o]]);export{u as __pageData,g as default};
